mapper.select:
SELECT IFNULL(SUM(paid), 0) AS income
FROM parking_order
WHERE is_deleted = 0
AND status = 1
AND paid_time >= #{begin}
AND paid_time < #{end}

    AND lot_id = #{lotId}

SELECT DATE_FORMAT(paid_time, '%Y-%m-%d') as date, IFNULL(SUM(paid), 0) as income FROM parking_order WHERE is_deleted = 0 AND status = 1 AND paid_time >= #{begin}
AND lot_id = #{lotId}
GROUP BY DATE_FORMAT(paid_time, '%Y-%m-%d')

SELECT DATE_FORMAT(entry_time, '%Y-%m-%d') AS date, COUNT(*) AS entryCount FROM entry_exit_record WHERE is_deleted = 0 AND entry_time >= #{begin}
AND lot_id = #{lotId}
GROUP BY DATE_FORMAT(entry_time, '%Y-%m-%d')

SELECT DATE_FORMAT(exit_time, '%Y-%m-%d') AS date, COUNT(*) AS exitCount FROM entry_exit_record WHERE is_deleted = 0 AND exit_time >= #{begin}
AND lot_id = #{lotId}
GROUP BY DATE_FORMAT(exit_time, '%Y-%m-%d')

SELECT status, COUNT(*) AS count FROM parking_order WHERE is_deleted = 0
AND lot_id = #{lotId}
GROUP BY status

SELECT pay_method as method, COUNT(*) as count, IFNULL(SUM(pr.amount), 0) as amount FROM payment_record pr
JOIN parking_order po ON pr.order_id = po.id AND po.lot_id = #{lotId}
WHERE pr.is_deleted = 0 GROUP BY pay_method

SELECT IFNULL(SUM(rf.amount), 0) FROM refund_record rf
JOIN parking_order po ON rf.order_id = po.id AND po.lot_id = #{lotId}
WHERE rf.is_deleted = 0
